import { generateProblem, problemTopicIds } from '../revision/problems/appliedMathsProblems'
import { generateSketch, sketchTopicIds } from '../revision/problems/appliedMathsSketches'
import { formatAnswer } from '../revision/problems/check'
import type { PracticeProblem } from '../revision/problems/types'
import { appliedMaths } from '../revision/subjects/appliedMaths'

/*
 * The Applied Mathematics files of the AI pack. Problems are generated by the
 * app's own generators from fixed seeds, so the answers are computed by the same
 * code the app uses and cannot drift from it. Run `npm run build:ai-pack` after
 * changing a generator.
 */

/** How many different problems each topic gets. */
export const VARIANTS_PER_TOPIC = 8

export const appliedMathsPackFiles = {
  topics: 'applied-maths-topics.json',
  networks: 'applied-maths-problems-networks.json',
  mechanics: 'applied-maths-problems-mechanics.json',
  difference: 'applied-maths-problems-difference-equations.json',
  sketches: 'applied-maths-sketches.json',
} as const

const strandFiles: Record<number, string> = {
  2: appliedMathsPackFiles.networks,
  3: appliedMathsPackFiles.mechanics,
  4: appliedMathsPackFiles.difference,
}

function problemEntry(problem: PracticeProblem) {
  return {
    statement: problem.statement,
    parts: problem.parts.map((part) => ({
      label: part.label,
      prompt: part.prompt,
      answer: part.answer,
      decimals: part.decimals,
      unit: part.unit,
      expected: formatAnswer(part),
    })),
    solution: problem.solution,
    ...(problem.diagram ? { diagram: problem.diagram } : {}),
  }
}

/** Distinct problems for a topic from fixed seeds; seeds that repeat a statement are skipped. */
function variants(topicId: string) {
  const seen = new Set<string>()
  const result = []
  for (let index = 1; index <= VARIANTS_PER_TOPIC * 3 && result.length < VARIANTS_PER_TOPIC; index += 1) {
    const problem = generateProblem(topicId, `pack-${index}`)
    if (!problem || seen.has(problem.statement)) continue
    seen.add(problem.statement)
    result.push(problemEntry(problem))
  }
  return result
}

export function buildAppliedMathsPack(): Record<string, unknown> {
  const withProblems = new Set(problemTopicIds())
  const withSketches = new Set(sketchTopicIds())
  const strandOf = new Map(appliedMaths.topics.map((topic) => [topic.id, topic.strand ?? 3]))
  const byFile: Record<string, Record<string, unknown>> = {}
  for (const topicId of problemTopicIds()) {
    const file = strandFiles[strandOf.get(topicId) ?? 3]
    byFile[file] ??= {}
    byFile[file][topicId] = variants(topicId)
  }

  const sketches: Record<string, unknown[]> = {}
  for (const topicId of sketchTopicIds()) {
    sketches[topicId] = [1, 2, 3, 4].flatMap((index) => {
      const sketch = generateSketch(topicId, `pack-${index}`)
      return sketch ? [{ prompt: sketch.prompt, checklist: sketch.checklist, reference: sketch.reference }] : []
    })
  }

  return {
    [appliedMathsPackFiles.topics]: {
      subject: 'Applied Mathematics (Leaving Certificate, Higher Level)',
      exam: 'One paper, 150 minutes: answer 8 of 10 questions on strands 2 to 4 (networks and graphs, mechanics, difference and differential equations). Strand 1, modelling, is assessed through the modelling project and the contexts of the questions. The official papers are not included: the student brings the question text from their own copy.',
      answerChecking: 'A numeric answer is correct when it is within 1% of `answer` or within the last rounding place given by `decimals`, whichever is larger. A comma may be used as the decimal point and units after the number are ignored.',
      topics: appliedMaths.topics.map((topic) => ({
        id: topic.id,
        title: topic.title,
        strand: topic.strand,
        higherOnly: topic.higherOnly,
        problemFile: withProblems.has(topic.id) ? strandFiles[topic.strand ?? 3] : null,
        hasSketches: withSketches.has(topic.id),
        recallPrompts: topic.recall ?? [],
      })),
      pastPaperPointers: {
        note: 'Own-words descriptions of where each topic appears in the official 2023 to 2026 Higher papers.',
        parts: appliedMaths.paperParts ?? [],
      },
    },
    [appliedMathsPackFiles.networks]: {
      note: 'Generated network problems. Each topic has several different problems. Diagrams list nodes and labelled edges. `parts[].answer` is the exact value; the student answers in the unit given.',
      problems: byFile[appliedMathsPackFiles.networks] ?? {},
    },
    [appliedMathsPackFiles.mechanics]: {
      note: 'Generated mechanics problems. Each topic has several different problems. `parts[].answer` is the exact value; the student answers in the unit given. Diagrams give data to read off a picture (a graph or a network).',
      problems: byFile[appliedMathsPackFiles.mechanics] ?? {},
    },
    [appliedMathsPackFiles.difference]: {
      note: 'Generated difference and differential equation problems. `parts[].answer` is the exact value; the student answers in the unit given.',
      problems: byFile[appliedMathsPackFiles.difference] ?? {},
    },
    [appliedMathsPackFiles.sketches]: {
      note: 'Drawing tasks. The student sketches on paper and sends a photo or describes the sketch. Compare it with `reference` (a description and data) and go through `checklist` one item at a time.',
      sketches,
    },
  }
}
